WITH base AS (SELECT *, CAST(amount AS INT) AS amount_int FROM payments WHERE order_id IS NOT NULL) SELECT CASE WHEN amount_int >= 75 THEN 'LARGE' ELSE 'SMALL' END AS amount_int_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, PERCENTILE_APPROX(amount_int, ARRAY(0.25, 0.5, 0.75)) AS amount_int_quartiles, MIN(paid_at) AS started_at, SUM(CASE WHEN method = 'card' THEN amount_int ELSE 0 END) AS card_amount_int, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM base GROUP BY CUBE (CASE WHEN amount_int >= 75 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', paid_at)) ORDER BY duration_min NULLS FIRST;
